mapper.sql:
alter table processing_rule_config alter column task_id drop not null; insert into processing_rule_config (id, parameter_range_check_enabled) select 1, coalesce(
(select parameter_range_check_enabled from processing_rule_config where scope_key = 'global' order by id desc limit 1),
(select parameter_range_check_enabled from processing_rule_config where id = 1), (select parameter_range_check_enabled from processing_rule_config order by update_time desc, id desc limit 1), 0 ) on conflict (id) do update set parameter_range_check_enabled = excluded.parameter_range_check_enabled, update_time = current_timestamp where processing_rule_config.parameter_range_check_enabled is distinct from excluded.parameter_range_check_enabled;
alter table processing_rule_config drop column if exists scope_key;

